\begin{proposition}[Compactness of Projective Space]
\label{exer:1-7}



\dcref{ch1:1.7}
$\mathbb{RP}^n$ is compact; the restriction
$\pi|_{\mathbb S^n}:\mathbb S^n\to\mathbb{RP}^n$ is surjective.
\end{proposition}

